            [
                'judul'          =>  'Dr. Laksanto Utomo Bersama 180 Perguruan Tinggi Hukum Indonesia Bentuk Tim Panel Eksaminasi Putusan MA',
                'slug'          =>  'dr-laksanto-utomo-bersama-180-perguruan-tinggi-hukum-indonesia-bentuk-tim-panel-eksaminasi-putusan-ma', 
                'id_user'      =>  'Admin',
